CREATE TABLE metric_definitions(metric_id uuid PRIMARY KEY,canonical_name text UNIQUE NOT NULL,unit text NOT NULL,value_kind text NOT NULL,is_flow boolean NOT NULL);
CREATE TABLE fundamental_source_mappings(mapping_id uuid PRIMARY KEY,source text NOT NULL,source_field text NOT NULL,metric_id uuid NOT NULL REFERENCES metric_definitions,source_unit text NOT NULL,scale numeric NOT NULL CHECK(scale>0),UNIQUE(source,source_field));
CREATE TABLE filings(filing_id uuid PRIMARY KEY,instrument_id uuid NOT NULL REFERENCES instruments,source text NOT NULL,source_filing_id text NOT NULL,revision text NOT NULL,report_type text NOT NULL,period_end date NOT NULL,announced_at timestamptz NOT NULL,available_at timestamptz NOT NULL,ingested_at timestamptz NOT NULL,raw_uri text NOT NULL,payload_hash text NOT NULL,status text NOT NULL,UNIQUE(source,source_filing_id,revision),CHECK(available_at>=announced_at));
CREATE TABLE fundamental_facts(fact_id uuid PRIMARY KEY,filing_id uuid NOT NULL REFERENCES filings,instrument_id uuid NOT NULL REFERENCES instruments,metric_id uuid NOT NULL REFERENCES metric_definitions,period_end date NOT NULL,period_type text NOT NULL,value numeric,unit text NOT NULL,currency char(3),raw_value text,lineage jsonb NOT NULL,source text NOT NULL,revision text NOT NULL,UNIQUE(instrument_id,metric_id,period_end,period_type,source,revision));
CREATE TABLE share_capital_changes(change_id uuid PRIMARY KEY,instrument_id uuid NOT NULL REFERENCES instruments,effective_date date NOT NULL,total_shares numeric NOT NULL CHECK(total_shares>0),float_shares numeric NOT NULL CHECK(float_shares>=0 AND float_shares<=total_shares),source text NOT NULL,announced_at timestamptz NOT NULL,available_at timestamptz NOT NULL,CHECK(available_at>=announced_at));
CREATE TABLE fundamental_quality_results(result_id uuid PRIMARY KEY,source text NOT NULL,source_filing_id text NOT NULL,revision text NOT NULL,code text NOT NULL,message text NOT NULL,field text);
CREATE TABLE fundamental_revision_events(event_id uuid PRIMARY KEY,filing_id uuid NOT NULL REFERENCES filings,instrument_id uuid NOT NULL REFERENCES instruments,old_revision text,new_revision text NOT NULL,affected jsonb NOT NULL,occurred_at timestamptz NOT NULL);
